import { Resend } from "resend";

// Transactional email, sent via Resend (https://resend.com).
//
// In development (or any environment missing RESEND_API_KEY) sends are
// logged to the console instead of hitting the network, so `npm run dev`
// works with no credentials configured.

export type SendEmailInput = {
  to: string;
  subject: string;
  html: string;
  text: string;
};

let cachedClient: Resend | null = null;

function getClient(): Resend | null {
  const apiKey = process.env.RESEND_API_KEY;
  if (!apiKey || apiKey === "re_placeholder_replace_me") {
    return null;
  }
  if (!cachedClient) {
    cachedClient = new Resend(apiKey);
  }
  return cachedClient;
}

export async function sendEmail(input: SendEmailInput): Promise<void> {
  const from = process.env.EMAIL_FROM ?? "Notely <onboarding@notely.example>";
  const client = getClient();

  if (!client) {
    // No API key configured — don't crash local dev, just log what would
    // have been sent.
    console.log(
      `[email:dev] RESEND_API_KEY not set, skipping send. Would have sent:\n` +
        `  to: ${input.to}\n  from: ${from}\n  subject: ${input.subject}\n` +
        `  text: ${input.text}`
    );
    return;
  }

  const { error } = await client.emails.send({
    from,
    to: input.to,
    subject: input.subject,
    html: input.html,
    text: input.text,
  });

  if (error) {
    throw new Error(`Failed to send email via Resend: ${error.message}`);
  }
}

