// Minimal, dependency-free HTML templates for transactional email.
// Kept intentionally simple (inline styles, table-free) — swap for
// react-email or MJML if the design needs grow.

function layout(title: string, bodyHtml: string): string {
  return `<!doctype html>
<html>
  <body style="margin:0;padding:0;background-color:#f4f4f5;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Helvetica,Arial,sans-serif;">
    <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#f4f4f5;padding:32px 0;">
      <tr>
        <td align="center">
          <table role="presentation" width="480" cellpadding="0" cellspacing="0" style="background-color:#ffffff;border-radius:8px;padding:32px;">
            <tr>
              <td>
                <p style="margin:0 0 24px;font-size:20px;font-weight:600;color:#18181b;">Notely</p>
                <h1 style="margin:0 0 16px;font-size:18px;color:#18181b;">${title}</h1>
                ${bodyHtml}
                <p style="margin:32px 0 0;font-size:12px;color:#a1a1aa;">Notely — a small team notes app.</p>
              </td>
            </tr>
          </table>
        </td>
      </tr>
    </table>
  </body>
</html>`;
}

export function welcomeEmail(name: string): { subject: string; html: string; text: string } {
  const subject = "Welcome to Notely";
  const html = layout(
    `Welcome, ${escapeHtml(name)} 👋`,
    `<p style="margin:0 0 12px;font-size:14px;line-height:1.6;color:#3f3f46;">
       Your Notely account is ready. You can jump into the dashboard and start
       sharing notes with your team right away.
     </p>`
  );
  const text = `Welcome to Notely, ${name}!\n\nYour account is ready. Head to the dashboard to get started.`;
  return { subject, html, text };
}

export function passwordResetEmail(resetUrl: string): {
  subject: string;
  html: string;
  text: string;
} {
  const subject = "Reset your Notely password";
  const html = layout(
    "Reset your password",
    `<p style="margin:0 0 12px;font-size:14px;line-height:1.6;color:#3f3f46;">
       We received a request to reset your Notely password. Click the button
       below to choose a new one. This link expires in 1 hour.
     </p>
     <p style="margin:24px 0;">
       <a href="${resetUrl}" style="display:inline-block;background-color:#18181b;color:#ffffff;
          text-decoration:none;padding:10px 20px;border-radius:6px;font-size:14px;font-weight:500;">
         Reset password
       </a>
     </p>
     <p style="margin:0;font-size:12px;line-height:1.6;color:#a1a1aa;">
       If you didn't request this, you can safely ignore this email.
     </p>`
  );
  const text = `Reset your Notely password: ${resetUrl}\n\nThis link expires in 1 hour. If you didn't request this, you can ignore this email.`;
  return { subject, html, text };
}

function escapeHtml(value: string): string {
  return value
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

